  /* V1229.16 — first-visit language detection. Before this, get() returned 'ar' for everyone with no
     stored choice, so a French/Chinese/Hindi/Spanish/Persian/English visitor always landed on Arabic
     regardless of their device language (and on phones the header picker was hidden, so they couldn't
     change it either). Now: an explicit saved choice always wins; otherwise walk the browser's
     preferred-language list in order and take the first one we support; if none is supported, fall
     back to English (the most widely understood option) instead of Arabic. Arabic-language browsers
     still get Arabic — detected, not hardcoded. */
  function detect(){
    try{
      const prefs=(navigator.languages&&navigator.languages.length)?navigator.languages:[navigator.language||''];
      for(const raw of prefs){const base=String(raw||'').toLowerCase().split('-')[0];if(LANGS.includes(base))return base}
    }catch(e){}
    return 'en';
  }
  function get(){const stored=localStorage.getItem(LANG_KEY);return LANGS.includes(stored)?stored:detect()}
  function set(lang){if(!LANGS.includes(lang))lang='ar';localStorage.setItem(LANG_KEY,lang);document.documentElement.lang=lang;document.documentElement.dir=DIR[lang];window.dispatchEvent(new CustomEvent('zivozone-language',{detail:{lang}}));return lang}
