  /* V1230.49 — Beauty Room (beauty-room.js) full translation: header/hero copy, tab labels, the 16 skin/body/recipe/habit cards, the brand editorial section, the safety note, and the exit-confirm dialog; found entirely hardcoded Arabic during the Phase C site-wide i18n audit. The mini-game and Epic50 content were already translated in an earlier round. */
  Object.assign(T.ar,{beautyRoomTitle:"غرفة الجمال",beautyRoomSubtitle:"مساحة راقية للعناية اليومية، المعرفة، والوصفات البسيطة للنساء والفتيات.",beautyHeroTitle:"الجمال يبدأ من العناية، لا من المثالية.",beautyHeroText:"معلومات عملية وروتينات بسيطة وأفكار آمنة نسبيًا للعناية بالبشرة والجسد والشعر، مع التأكيد أن مشاكل البشرة المستمرة تحتاج تقييمًا مختصًا.",beautyTabSkin:"العناية بالبشرة",beautyTabBody:"العناية بالجسد والشعر",beautyTabRecipes:"وصفات لطيفة",beautyTabHabits:"عادات الجمال",beautyChooseLabel:"اختاري ما يهمك",beautyBrandNote:"عرض تحريري لعلامة إكسسوارات معروفة؛ لا تمثل هذه المساحة شراكة أو رعاية رسمية. يمكن استبدال العلامة لاحقًا بعلامة شريكة حقيقية عند توفر اتفاق.",beautyBrandLookTitle:"إطلالة راقية",beautyBrandLookText:"اختاري قطعة واحدة مميزة أو نسّقي قطعًا بسيطة بدل ازدحام الإكسسوارات.",beautyNoteTitle:"ملاحظة مهمة",beautyNoteText:"المحتوى تثقيفي عام وليس تشخيصًا أو علاجًا طبيًا. اختبري أي منتج جديد على مساحة صغيرة، وتوقفي عند حدوث تهيج. في الحالات المستمرة أو الشديدة راجعي طبيبة جلدية.",beautyExitConfirm:"هل أنت متأكدة من مغادرة غرفة الجمال والعودة إلى الموقع؟",beautySkinTitle1:"روتين الصباح",beautySkinDesc1:"منظف لطيف → مرطب مناسب → واقي شمس واسع الطيف. البساطة أفضل من ازدحام المنتجات.",beautySkinTitle2:"روتين المساء",beautySkinDesc2:"إزالة المكياج بلطف → تنظيف → مرطب. أضيفي أي مادة فعالة تدريجيًا وليس كلها معًا.",beautySkinTitle3:"البشرة الجافة",beautySkinDesc3:"ابحثي عن مرطبات تحتوي على مكونات داعمة للحاجز مثل السيراميدات أو الغليسرين، وتجنبي الماء شديد السخونة.",beautySkinTitle4:"البشرة الدهنية",beautySkinDesc4:"التنظيف اللطيف مهم، وتجنبي الإفراط في التجفيف لأنه قد يزيد التهيج. اختاري منتجات غير كوميدوغينية عند الحاجة.",beautySkinTitle5:"البشرة الحساسة",beautySkinDesc5:"اختبري المنتج على مساحة صغيرة أولًا، وأوقفيه عند حدوث حرقان أو طفح مستمر.",beautyBodyTitle1:"الاستحمام الذكي",beautyBodyDesc1:"ماء فاتر، مدة معتدلة، وتجفيف بالتربيت بدل الفرك القوي.",beautyBodyTitle2:"الترطيب",beautyBodyDesc2:"ضعي المرطب بعد الاستحمام مباشرة عندما تكون البشرة رطبة قليلًا للمساعدة على حفظ الرطوبة.",beautyBodyTitle3:"العناية باليدين",beautyBodyDesc3:"مرطب بعد غسل اليدين، مع الاهتمام بالأظافر والجلد المحيط بها دون قص الجلد بقسوة.",beautyBodyTitle4:"العناية بالشعر",beautyBodyDesc4:"اختاري الشامبو حسب فروة الرأس والبلسم حسب أطراف الشعر، وقللي الحرارة العالية المتكررة.",beautyRecipeTitle1:"قناع الشوفان اللطيف",beautyRecipeDesc1:"اخلطي شوفانًا مطحونًا ناعمًا مع قليل من الماء حتى يصبح معجونًا ناعمًا. ضعيه لفترة قصيرة ثم اغسليه بلطف. لا تستخدميه على جلد متشقق.",beautyRecipeTitle2:"كمادة ترطيب بسيطة",beautyRecipeDesc2:"قطعة قماش نظيفة بماء فاتر لبضع دقائق ثم مرطب مناسب بعد ذلك. خيار بسيط بدل خلطات قوية.",beautyRecipeTitle3:"مقشر آمن؟",beautyRecipeDesc3:"الأفضل عدم الاعتماد على وصفات منزلية خشنة مثل السكر أو الملح على الوجه. اختاري مقشرًا مخصصًا للبشرة عند الحاجة واتّبعي تعليماته.",beautyHabitTitle1:"النوم",beautyHabitDesc1:"الانتظام في النوم ينعكس على الطاقة والمظهر العام.",beautyHabitTitle2:"الماء والطعام",beautyHabitDesc2:"الترطيب والغذاء المتوازن جزء من العناية العامة، وليس هناك مشروب سحري للبشرة.",beautyHabitTitle3:"النظافة",beautyHabitDesc3:"نظفي أدوات المكياج والفرش بانتظام ولا تشاركي مستحضرات العين مع الآخرين.",beautyHabitTitle4:"الحماية من الشمس",beautyHabitDesc4:"الوقاية اليومية من الشمس من أهم العادات طويلة المدى للعناية بالبشرة."});
  Object.assign(T.en,{beautyRoomTitle:"Beauty Room",beautyRoomSubtitle:"A refined space for daily care, knowledge, and simple recipes for women and girls.",beautyHeroTitle:"Beauty starts with care, not perfection.",beautyHeroText:"Practical information, simple routines, and relatively safe ideas for skin, body, and hair care — with the reminder that persistent skin issues need a specialist's assessment.",beautyTabSkin:"Skin Care",beautyTabBody:"Body & Hair Care",beautyTabRecipes:"Gentle Recipes",beautyTabHabits:"Beauty Habits",beautyChooseLabel:"Choose what matters to you",beautyBrandNote:"An editorial feature on a well-known accessories brand; this space does not represent an official partnership or sponsorship. The brand may be replaced later with a real partner brand when an agreement is in place.",beautyBrandLookTitle:"A refined look",beautyBrandLookText:"Pick one standout piece or coordinate simple pieces instead of crowding on accessories.",beautyNoteTitle:"Important note",beautyNoteText:"This content is general education, not a medical diagnosis or treatment. Test any new product on a small area and stop if irritation occurs. For persistent or severe cases, see a dermatologist.",beautyExitConfirm:"Are you sure you want to leave the Beauty Room and go back to the site?",beautySkinTitle1:"Morning Routine",beautySkinDesc1:"Gentle cleanser → suitable moisturizer → broad-spectrum sunscreen. Simplicity beats a crowded routine.",beautySkinTitle2:"Evening Routine",beautySkinDesc2:"Gently remove makeup → cleanse → moisturize. Add any active ingredient gradually, not all at once.",beautySkinTitle3:"Dry Skin",beautySkinDesc3:"Look for moisturizers with barrier-supporting ingredients like ceramides or glycerin, and avoid very hot water.",beautySkinTitle4:"Oily Skin",beautySkinDesc4:"Gentle cleansing matters, and avoid over-drying, since it can increase irritation. Choose non-comedogenic products when needed.",beautySkinTitle5:"Sensitive Skin",beautySkinDesc5:"Test any product on a small area first, and stop if burning or a persistent rash occurs.",beautyBodyTitle1:"Smart Showering",beautyBodyDesc1:"Lukewarm water, a moderate duration, and pat drying instead of hard rubbing.",beautyBodyTitle2:"Moisturizing",beautyBodyDesc2:"Apply moisturizer right after showering while the skin is still slightly damp, to help lock in moisture.",beautyBodyTitle3:"Hand Care",beautyBodyDesc3:"Moisturize after washing your hands, and care for nails and the surrounding skin without cutting the skin roughly.",beautyBodyTitle4:"Hair Care",beautyBodyDesc4:"Choose shampoo based on your scalp and conditioner based on your hair ends, and cut back on frequent high heat.",beautyRecipeTitle1:"Gentle Oat Mask",beautyRecipeDesc1:"Mix finely ground oats with a little water until it forms a smooth paste. Apply briefly, then rinse gently. Don't use it on cracked skin.",beautyRecipeTitle2:"Simple Hydrating Compress",beautyRecipeDesc2:"A clean cloth with lukewarm water for a few minutes, then a suitable moisturizer afterward. A simple option instead of harsh mixtures.",beautyRecipeTitle3:"A Safe Scrub?",beautyRecipeDesc3:"It's best not to rely on rough homemade recipes like sugar or salt on the face. Choose a scrub made for skin when needed and follow its instructions.",beautyHabitTitle1:"Sleep",beautyHabitDesc1:"Consistent sleep shows up in your energy and overall appearance.",beautyHabitTitle2:"Water & Food",beautyHabitDesc2:"Hydration and balanced nutrition are part of overall care, and there's no magic drink for skin.",beautyHabitTitle3:"Hygiene",beautyHabitDesc3:"Clean your makeup tools and brushes regularly, and don't share eye products with others.",beautyHabitTitle4:"Sun Protection",beautyHabitDesc4:"Daily sun protection is one of the most important long-term habits for skin care."});
  Object.assign(T.zh,{beautyRoomTitle:"美丽空间",beautyRoomSubtitle:"一个优雅的空间，提供日常护理知识和简单配方，专为女性和女孩打造。",beautyHeroTitle:"美丽源于呵护，而非完美。",beautyHeroText:"实用信息、简单的护理流程，以及相对安全的皮肤、身体和头发护理方法——同时提醒持续存在的皮肤问题需要专业评估。",beautyTabSkin:"皮肤护理",beautyTabBody:"身体与头发护理",beautyTabRecipes:"温和配方",beautyTabHabits:"美丽习惯",beautyChooseLabel:"选择你关心的内容",beautyBrandNote:"这是对一个知名配饰品牌的编辑性展示；此空间不代表官方合作或赞助关系。日后可在达成协议后，将该品牌替换为真正的合作品牌。",beautyBrandLookTitle:"优雅造型",beautyBrandLookText:"选一件出众的单品，或搭配简洁的饰品，而不是堆砌配饰。",beautyNoteTitle:"重要提示",beautyNoteText:"本内容为一般性知识普及，并非医学诊断或治疗。使用任何新产品前请先在小范围测试，若出现刺激请立即停用。对于持续或严重的情况，请咨询皮肤科医生。",beautyExitConfirm:"你确定要离开美丽空间并返回网站吗？",beautySkinTitle1:"晨间护理",beautySkinDesc1:"温和洁面 → 合适的保湿霜 → 广谱防晒。简单比堆砌产品更好。",beautySkinTitle2:"晚间护理",beautySkinDesc2:"温和卸妆 → 清洁 → 保湿。逐步添加功效成分，而不是一次全部使用。",beautySkinTitle3:"干性皮肤",beautySkinDesc3:"寻找含有神经酰胺或甘油等支持屏障成分的保湿产品，并避免使用过热的水。",beautySkinTitle4:"油性皮肤",beautySkinDesc4:"温和清洁很重要，避免过度干燥，因为这可能加重刺激。需要时选择不致粉刺的产品。",beautySkinTitle5:"敏感皮肤",beautySkinDesc5:"先在小范围测试任何产品，若出现灼热感或持续皮疹请立即停用。",beautyBodyTitle1:"聪明沐浴",beautyBodyDesc1:"温水、适度的时长，用轻拍代替用力摩擦来擦干身体。",beautyBodyTitle2:"身体保湿",beautyBodyDesc2:"沐浴后趁皮肤还略带潮湿时立即涂抹保湿霜，帮助锁住水分。",beautyBodyTitle3:"手部护理",beautyBodyDesc3:"洗手后使用护手霜，并照顾好指甲和周围的皮肤，不要粗暴地剪皮肤。",beautyBodyTitle4:"头发护理",beautyBodyDesc4:"根据头皮状况选择洗发水，根据发尾状况选择护发素，并减少频繁的高温造型。",beautyRecipeTitle1:"温和燕麦面膜",beautyRecipeDesc1:"将细磨燕麦与少量水混合，调成细腻的糊状。敷上短暂时间后轻轻冲洗掉。不要用于有裂口的皮肤。",beautyRecipeTitle2:"简单补水敷布",beautyRecipeDesc2:"用干净的布蘸温水敷几分钟，之后再涂上合适的保湿霜。这是替代刺激性混合物的简单选择。",beautyRecipeTitle3:"安全的去角质方法？",beautyRecipeDesc3:"最好不要依赖像糖或盐这类粗糙的居家配方涂在脸上。需要时请选择专为皮肤设计的去角质产品，并遵循其说明。",beautyHabitTitle1:"睡眠",beautyHabitDesc1:"规律的睡眠会体现在你的精力和整体外貌上。",beautyHabitTitle2:"水分与饮食",beautyHabitDesc2:"补水和均衡饮食是整体护理的一部分，并没有什么神奇的护肤饮品。",beautyHabitTitle3:"卫生习惯",beautyHabitDesc3:"定期清洁化妆工具和刷子，不要与他人共用眼部产品。",beautyHabitTitle4:"防晒",beautyHabitDesc4:"每日防晒是皮肤护理中最重要的长期习惯之一。"});
  Object.assign(T.hi,{beautyRoomTitle:"ब्यूटी रूम",beautyRoomSubtitle:"महिलाओं और लड़कियों के लिए दैनिक देखभाल, जानकारी और सरल नुस्खों की एक परिष्कृत जगह।",beautyHeroTitle:"सुंदरता देखभाल से शुरू होती है, पूर्णता से नहीं।",beautyHeroText:"त्वचा, शरीर और बालों की देखभाल के लिए व्यावहारिक जानकारी, सरल रूटीन और अपेक्षाकृत सुरक्षित सुझाव — साथ में यह याद दिलाते हुए कि लगातार बनी रहने वाली त्वचा समस्याओं के लिए विशेषज्ञ की जाँच ज़रूरी है।",beautyTabSkin:"त्वचा की देखभाल",beautyTabBody:"शरीर और बालों की देखभाल",beautyTabRecipes:"सौम्य नुस्खे",beautyTabHabits:"सुंदरता की आदतें",beautyChooseLabel:"वह चुनें जो आपके लिए मायने रखता है",beautyBrandNote:"यह एक जाने-माने एक्सेसरीज़ ब्रांड की संपादकीय झलक है; यह जगह किसी आधिकारिक साझेदारी या प्रायोजन का प्रतिनिधित्व नहीं करती। समझौता होने पर इस ब्रांड को बाद में किसी वास्तविक साझेदार ब्रांड से बदला जा सकता है।",beautyBrandLookTitle:"एक परिष्कृत लुक",beautyBrandLookText:"एक्सेसरीज़ की भीड़ लगाने के बजाय एक खास टुकड़ा चुनें या सरल टुकड़ों को मिलाएं।",beautyNoteTitle:"महत्वपूर्ण टिप्पणी",beautyNoteText:"यह सामग्री सामान्य जानकारी के लिए है, न कि कोई चिकित्सा निदान या उपचार। कोई भी नया उत्पाद पहले एक छोटे हिस्से पर आज़माएं, और जलन होने पर रोक दें। लगातार या गंभीर स्थितियों में त्वचा रोग विशेषज्ञ से सलाह लें।",beautyExitConfirm:"क्या आप वाकई ब्यूटी रूम छोड़कर साइट पर वापस जाना चाहती हैं?",beautySkinTitle1:"सुबह की रूटीन",beautySkinDesc1:"माइल्ड क्लींजर → उपयुक्त मॉइस्चराइज़र → ब्रॉड-स्पेक्ट्रम सनस्क्रीन। सादगी उत्पादों की भीड़ से बेहतर है।",beautySkinTitle2:"रात की रूटीन",beautySkinDesc2:"मेकअप धीरे से हटाएं → क्लींज करें → मॉइस्चराइज़ करें। कोई भी एक्टिव इंग्रीडिएंट धीरे-धीरे शामिल करें, एक साथ नहीं।",beautySkinTitle3:"रूखी त्वचा",beautySkinDesc3:"सेरामाइड्स या ग्लिसरीन जैसे बैरियर-सपोर्टिंग तत्वों वाले मॉइस्चराइज़र चुनें, और बहुत गर्म पानी से बचें।",beautySkinTitle4:"तैलीय त्वचा",beautySkinDesc4:"सौम्य क्लींज़िंग ज़रूरी है, और अधिक सूखने से बचें क्योंकि यह जलन बढ़ा सकता है। ज़रूरत पड़ने पर नॉन-कॉमेडोजेनिक उत्पाद चुनें।",beautySkinTitle5:"संवेदनशील त्वचा",beautySkinDesc5:"पहले किसी भी उत्पाद को एक छोटे हिस्से पर आज़माएं, और जलन या लगातार रैश होने पर रोक दें।",beautyBodyTitle1:"समझदारी से स्नान",beautyBodyDesc1:"गुनगुना पानी, मध्यम अवधि, और ज़ोर से रगड़ने के बजाय थपथपाकर सुखाना।",beautyBodyTitle2:"त्वचा को नमी देना",beautyBodyDesc2:"स्नान के ठीक बाद, जब त्वचा थोड़ी नम हो, मॉइस्चराइज़र लगाएं जिससे नमी बनी रहे।",beautyBodyTitle3:"हाथों की देखभाल",beautyBodyDesc3:"हाथ धोने के बाद मॉइस्चराइज़र लगाएं, और नाखूनों व आसपास की त्वचा का ध्यान रखें बिना त्वचा को ज़ोर से काटे।",beautyBodyTitle4:"बालों की देखभाल",beautyBodyDesc4:"स्कैल्प के अनुसार शैम्पू और बालों के सिरों के अनुसार कंडीशनर चुनें, और बार-बार तेज़ हीट का उपयोग कम करें।",beautyRecipeTitle1:"सौम्य ओट मास्क",beautyRecipeDesc1:"बारीक पिसे ओट्स को थोड़े पानी के साथ मिलाकर एक मुलायम पेस्ट बनाएं। थोड़ी देर लगाकर धीरे से धो लें। फटी त्वचा पर इसका इस्तेमाल न करें।",beautyRecipeTitle2:"सरल हाइड्रेटिंग कंप्रेस",beautyRecipeDesc2:"एक साफ कपड़े को गुनगुने पानी में कुछ मिनट भिगोएं, फिर उसके बाद उपयुक्त मॉइस्चराइज़र लगाएं। तेज़ मिश्रणों के बजाय एक सरल विकल्प।",beautyRecipeTitle3:"क्या स्क्रब सुरक्षित है?",beautyRecipeDesc3:"चेहरे पर चीनी या नमक जैसे रूखे घरेलू नुस्खों पर निर्भर न रहना बेहतर है। ज़रूरत पड़ने पर त्वचा के लिए बनाए गए स्क्रब चुनें और उसके निर्देशों का पालन करें।",beautyHabitTitle1:"नींद",beautyHabitDesc1:"नियमित नींद आपकी ऊर्जा और समग्र रूप-रंग में झलकती है।",beautyHabitTitle2:"पानी और भोजन",beautyHabitDesc2:"हाइड्रेशन और संतुलित आहार समग्र देखभाल का हिस्सा हैं, और त्वचा के लिए कोई जादुई पेय नहीं है।",beautyHabitTitle3:"स्वच्छता",beautyHabitDesc3:"अपने मेकअप टूल्स और ब्रश नियमित रूप से साफ करें, और आई प्रोडक्ट्स दूसरों के साथ साझा न करें।",beautyHabitTitle4:"सूरज से सुरक्षा",beautyHabitDesc4:"रोज़ाना सूरज से सुरक्षा त्वचा की देखभाल की सबसे महत्वपूर्ण लंबी अवधि की आदतों में से एक है।"});
  Object.assign(T.es,{beautyRoomTitle:"Sala de Belleza",beautyRoomSubtitle:"Un espacio refinado para el cuidado diario, el conocimiento y recetas sencillas para mujeres y niñas.",beautyHeroTitle:"La belleza empieza con el cuidado, no con la perfección.",beautyHeroText:"Información práctica, rutinas sencillas e ideas relativamente seguras para el cuidado de la piel, el cuerpo y el cabello, recordando que los problemas de piel persistentes necesitan una evaluación especializada.",beautyTabSkin:"Cuidado de la Piel",beautyTabBody:"Cuidado del Cuerpo y el Cabello",beautyTabRecipes:"Recetas Suaves",beautyTabHabits:"Hábitos de Belleza",beautyChooseLabel:"Elige lo que te importa",beautyBrandNote:"Una presentación editorial de una marca de accesorios conocida; este espacio no representa una asociación o patrocinio oficial. La marca podría reemplazarse más adelante por una marca socia real cuando exista un acuerdo.",beautyBrandLookTitle:"Un look refinado",beautyBrandLookText:"Elige una pieza destacada o combina piezas sencillas en vez de amontonar accesorios.",beautyNoteTitle:"Nota importante",beautyNoteText:"Este contenido es educativo general, no un diagnóstico ni un tratamiento médico. Prueba cualquier producto nuevo en una zona pequeña y detente si aparece irritación. En casos persistentes o graves, consulta a una dermatóloga.",beautyExitConfirm:"¿Seguro que quieres salir de la Sala de Belleza y volver al sitio?",beautySkinTitle1:"Rutina de Mañana",beautySkinDesc1:"Limpiador suave → hidratante adecuado → protector solar de amplio espectro. La sencillez es mejor que amontonar productos.",beautySkinTitle2:"Rutina de Noche",beautySkinDesc2:"Retira el maquillaje con suavidad → limpia → hidrata. Añade cualquier activo de forma gradual, no todos a la vez.",beautySkinTitle3:"Piel Seca",beautySkinDesc3:"Busca hidratantes con ingredientes que apoyen la barrera cutánea, como ceramidas o glicerina, y evita el agua muy caliente.",beautySkinTitle4:"Piel Grasa",beautySkinDesc4:"La limpieza suave importa, y evita el exceso de resequedad porque puede aumentar la irritación. Elige productos no comedogénicos cuando lo necesites.",beautySkinTitle5:"Piel Sensible",beautySkinDesc5:"Prueba cualquier producto primero en una zona pequeña, y detente si aparece ardor o un sarpullido persistente.",beautyBodyTitle1:"Ducha Inteligente",beautyBodyDesc1:"Agua tibia, una duración moderada, y secar dando toques en vez de frotar con fuerza.",beautyBodyTitle2:"Hidratación",beautyBodyDesc2:"Aplica la crema hidratante justo después de la ducha, cuando la piel aún está algo húmeda, para ayudar a retener la humedad.",beautyBodyTitle3:"Cuidado de las Manos",beautyBodyDesc3:"Hidrata después de lavarte las manos, y cuida las uñas y la piel alrededor sin cortarla con brusquedad.",beautyBodyTitle4:"Cuidado del Cabello",beautyBodyDesc4:"Elige el champú según tu cuero cabelludo y el acondicionador según las puntas de tu cabello, y reduce el calor alto frecuente.",beautyRecipeTitle1:"Mascarilla Suave de Avena",beautyRecipeDesc1:"Mezcla avena molida fina con un poco de agua hasta formar una pasta suave. Aplícala brevemente y luego acláralá con suavidad. No la uses sobre piel agrietada.",beautyRecipeTitle2:"Compresa Hidratante Sencilla",beautyRecipeDesc2:"Un paño limpio con agua tibia durante unos minutos, y luego una crema hidratante adecuada. Una opción sencilla en vez de mezclas agresivas.",beautyRecipeTitle3:"¿Un exfoliante seguro?",beautyRecipeDesc3:"Es mejor no depender de recetas caseras ásperas como azúcar o sal sobre el rostro. Elige un exfoliante hecho para la piel cuando lo necesites y sigue sus instrucciones.",beautyHabitTitle1:"Sueño",beautyHabitDesc1:"Un sueño constante se refleja en tu energía y tu aspecto general.",beautyHabitTitle2:"Agua y Alimentación",beautyHabitDesc2:"La hidratación y una alimentación equilibrada son parte del cuidado general, y no existe una bebida mágica para la piel.",beautyHabitTitle3:"Higiene",beautyHabitDesc3:"Limpia tus herramientas de maquillaje y brochas con regularidad, y no compartas productos para ojos con otras personas.",beautyHabitTitle4:"Protección Solar",beautyHabitDesc4:"La protección solar diaria es uno de los hábitos a largo plazo más importantes para el cuidado de la piel."});
  Object.assign(T.fr,{beautyRoomTitle:"Salle Beauté",beautyRoomSubtitle:"Un espace raffiné pour les soins quotidiens, les connaissances et des recettes simples pour les femmes et les filles.",beautyHeroTitle:"La beauté commence par le soin, pas par la perfection.",beautyHeroText:"Des informations pratiques, des routines simples et des idées relativement sûres pour le soin de la peau, du corps et des cheveux, avec le rappel que les problèmes de peau persistants nécessitent une évaluation spécialisée.",beautyTabSkin:"Soin de la Peau",beautyTabBody:"Soin du Corps et des Cheveux",beautyTabRecipes:"Recettes Douces",beautyTabHabits:"Habitudes Beauté",beautyChooseLabel:"Choisis ce qui compte pour toi",beautyBrandNote:"Une présentation éditoriale d'une marque d'accessoires connue ; cet espace ne représente pas un partenariat ou un parrainage officiel. La marque pourra être remplacée plus tard par une véritable marque partenaire lorsqu'un accord sera en place.",beautyBrandLookTitle:"Un look raffiné",beautyBrandLookText:"Choisis une pièce marquante ou assortis des pièces simples plutôt que d'accumuler les accessoires.",beautyNoteTitle:"Remarque importante",beautyNoteText:"Ce contenu est à visée éducative générale, ce n'est pas un diagnostic ni un traitement médical. Teste tout nouveau produit sur une petite zone et arrête en cas d'irritation. En cas de problème persistant ou sévère, consulte une dermatologue.",beautyExitConfirm:"Es-tu sûre de vouloir quitter la Salle Beauté et revenir au site ?",beautySkinTitle1:"Routine du Matin",beautySkinDesc1:"Nettoyant doux → hydratant adapté → écran solaire à large spectre. La simplicité vaut mieux qu'une routine surchargée.",beautySkinTitle2:"Routine du Soir",beautySkinDesc2:"Démaquille en douceur → nettoie → hydrate. Ajoute tout actif progressivement, pas tous en même temps.",beautySkinTitle3:"Peau Sèche",beautySkinDesc3:"Cherche des hydratants contenant des ingrédients qui soutiennent la barrière cutanée, comme les céramides ou la glycérine, et évite l'eau très chaude.",beautySkinTitle4:"Peau Grasse",beautySkinDesc4:"Un nettoyage doux compte, et évite le dessèchement excessif, qui peut augmenter l'irritation. Choisis des produits non comédogènes si besoin.",beautySkinTitle5:"Peau Sensible",beautySkinDesc5:"Teste d'abord tout produit sur une petite zone, et arrête en cas de brûlure ou d'éruption persistante.",beautyBodyTitle1:"Douche Intelligente",beautyBodyDesc1:"Eau tiède, durée modérée, et séchage en tamponnant plutôt qu'en frottant fort.",beautyBodyTitle2:"Hydratation",beautyBodyDesc2:"Applique la crème hydratante juste après la douche, quand la peau est encore légèrement humide, pour aider à retenir l'humidité.",beautyBodyTitle3:"Soin des Mains",beautyBodyDesc3:"Hydrate après t'être lavé les mains, et prends soin des ongles et de la peau autour sans la couper brutalement.",beautyBodyTitle4:"Soin des Cheveux",beautyBodyDesc4:"Choisis le shampoing selon ton cuir chevelu et l'après-shampoing selon les pointes, et réduis la chaleur élevée fréquente.",beautyRecipeTitle1:"Masque Doux à l'Avoine",beautyRecipeDesc1:"Mélange de l'avoine finement moulue avec un peu d'eau jusqu'à obtenir une pâte lisse. Applique brièvement, puis rince en douceur. Ne l'utilise pas sur une peau craquelée.",beautyRecipeTitle2:"Compresse Hydratante Simple",beautyRecipeDesc2:"Un linge propre avec de l'eau tiède pendant quelques minutes, puis un hydratant adapté ensuite. Une option simple au lieu de mélanges agressifs.",beautyRecipeTitle3:"Un gommage sûr ?",beautyRecipeDesc3:"Mieux vaut ne pas compter sur des recettes maison rugueuses comme le sucre ou le sel sur le visage. Choisis un gommage conçu pour la peau quand c'est nécessaire et suis ses instructions.",beautyHabitTitle1:"Sommeil",beautyHabitDesc1:"Un sommeil régulier se reflète sur ton énergie et ton apparence générale.",beautyHabitTitle2:"Eau et Alimentation",beautyHabitDesc2:"L'hydratation et une alimentation équilibrée font partie du soin global, et il n'existe pas de boisson magique pour la peau.",beautyHabitTitle3:"Hygiène",beautyHabitDesc3:"Nettoie régulièrement tes outils de maquillage et tes pinceaux, et ne partage pas tes produits pour les yeux avec d'autres personnes.",beautyHabitTitle4:"Protection Solaire",beautyHabitDesc4:"La protection solaire quotidienne est l'une des habitudes à long terme les plus importantes pour le soin de la peau."});
  Object.assign(T.fa,{beautyRoomTitle:"اتاق زیبایی",beautyRoomSubtitle:"فضایی برازنده برای مراقبت روزانه، دانش و دستورهای ساده برای زنان و دختران.",beautyHeroTitle:"زیبایی با مراقبت شروع می‌شود، نه با کمال.",beautyHeroText:"اطلاعات کاربردی، روتین‌های ساده و ایده‌های نسبتاً بی‌خطر برای مراقبت از پوست، بدن و مو، همراه با این یادآوری که مشکلات پوستی مداوم نیاز به ارزیابی متخصص دارند.",beautyTabSkin:"مراقبت از پوست",beautyTabBody:"مراقبت از بدن و مو",beautyTabRecipes:"دستورهای ملایم",beautyTabHabits:"عادات زیبایی",beautyChooseLabel:"آنچه برایت مهم است را انتخاب کن",beautyBrandNote:"این یک معرفی ویرایشی از یک برند اکسسوری شناخته‌شده است؛ این بخش نشان‌دهنده‌ی مشارکت یا حمایت رسمی نیست. این برند ممکن است بعداً، در صورت توافق، با یک برند همکار واقعی جایگزین شود.",beautyBrandLookTitle:"ظاهری برازنده",beautyBrandLookText:"به‌جای انباشتن اکسسوری، یک قطعه‌ی خاص انتخاب کن یا قطعات ساده را هماهنگ کن.",beautyNoteTitle:"نکته‌ی مهم",beautyNoteText:"این محتوا آموزشی عمومی است و تشخیص یا درمان پزشکی نیست. هر محصول جدید را ابتدا روی یک ناحیه‌ی کوچک آزمایش کن و در صورت تحریک متوقف شو. در موارد مداوم یا شدید، به متخصص پوست مراجعه کن.",beautyExitConfirm:"آیا مطمئنی می‌خواهی اتاق زیبایی را ترک کنی و به سایت برگردی؟",beautySkinTitle1:"روتین صبح",beautySkinDesc1:"شوینده ملایم → مرطوب‌کننده مناسب → ضدآفتاب طیف‌وسیع. سادگی بهتر از انباشتن محصولات است.",beautySkinTitle2:"روتین شب",beautySkinDesc2:"آرایش را به‌آرامی پاک کن → شست‌وشو بده → مرطوب کن. هر ماده‌ی فعال را به‌تدریج اضافه کن، نه همه را یک‌جا.",beautySkinTitle3:"پوست خشک",beautySkinDesc3:"مرطوب‌کننده‌هایی با مواد تقویت‌کننده‌ی سد پوستی مانند سرامید یا گلیسیرین را انتخاب کن، و از آب بسیار داغ پرهیز کن.",beautySkinTitle4:"پوست چرب",beautySkinDesc4:"شست‌وشوی ملایم مهم است، و از خشک‌کردن بیش‌ازحد پرهیز کن چون می‌تواند تحریک را بیشتر کند. در صورت نیاز محصولات غیرکومدوژنیک را انتخاب کن.",beautySkinTitle5:"پوست حساس",beautySkinDesc5:"هر محصول را ابتدا روی یک ناحیه‌ی کوچک آزمایش کن، و در صورت سوزش یا جوش مداوم متوقف شو.",beautyBodyTitle1:"حمام هوشمند",beautyBodyDesc1:"آب ولرم، مدت متوسط، و خشک‌کردن با ضربه‌ی آرام به‌جای مالش شدید.",beautyBodyTitle2:"مرطوب‌سازی",beautyBodyDesc2:"بلافاصله بعد از حمام، وقتی پوست هنوز کمی مرطوب است، مرطوب‌کننده بزن تا رطوبت حفظ شود.",beautyBodyTitle3:"مراقبت از دست‌ها",beautyBodyDesc3:"بعد از شستن دست‌ها مرطوب‌کننده بزن، و به ناخن‌ها و پوست اطرافشان توجه کن بدون اینکه پوست را به‌زور ببری.",beautyBodyTitle4:"مراقبت از مو",beautyBodyDesc4:"شامپو را بر اساس پوست سر و نرم‌کننده را بر اساس نوک موها انتخاب کن، و استفاده‌ی مکرر از حرارت زیاد را کم کن.",beautyRecipeTitle1:"ماسک ملایم جو دوسر",beautyRecipeDesc1:"جو دوسر آردشده را با کمی آب مخلوط کن تا خمیری نرم شود. مدت کوتاهی بگذار و سپس به‌آرامی بشور. روی پوست ترک‌خورده استفاده نکن.",beautyRecipeTitle2:"کمپرس آبرسان ساده",beautyRecipeDesc2:"یک دستمال تمیز با آب ولرم به مدت چند دقیقه، و سپس مرطوب‌کننده‌ی مناسب. گزینه‌ای ساده به‌جای ترکیبات تهاجمی.",beautyRecipeTitle3:"اسکراب بی‌خطر؟",beautyRecipeDesc3:"بهتر است به دستورهای خانگی زبر مثل شکر یا نمک روی صورت تکیه نکنی. در صورت نیاز اسکرابی مخصوص پوست انتخاب کن و دستورالعمل آن را دنبال کن.",beautyHabitTitle1:"خواب",beautyHabitDesc1:"خواب منظم در انرژی و ظاهر کلی تو نمایان می‌شود.",beautyHabitTitle2:"آب و غذا",beautyHabitDesc2:"آبرسانی و تغذیه‌ی متوازن بخشی از مراقبت کلی هستند، و نوشیدنی معجزه‌آسایی برای پوست وجود ندارد.",beautyHabitTitle3:"بهداشت",beautyHabitDesc3:"ابزار آرایش و براش‌هایت را به‌طور منظم تمیز کن، و محصولات چشم را با دیگران به اشتراک نگذار.",beautyHabitTitle4:"محافظت در برابر آفتاب",beautyHabitDesc4:"محافظت روزانه در برابر آفتاب یکی از مهم‌ترین عادت‌های بلندمدت برای مراقبت از پوست است."});

