  Object.assign(T.ar,{identityIntroEyebrow:"تحليل الشخصية",identityIntroTitle:"قبل أن نبدأ معك…",identityIntroBody:"٢٠ سؤالًا بسيطًا، بلا عدّاد زمني وبلا ضغط. أجب بصدق وعلى راحتك — لا توجد إجابة صحيحة أو خاطئة، فقط إجابتك الحقيقية. كل ما نحتاجه هو أن تكون أنت.",identityIntroDisclaimer:"هذا التحليل مصمم لمساعدتك على فهم نفسك بشكل أعمق وممتع، وهو ليس تشخيصًا طبيًا أو نفسيًا ولا يُستخدم بديلًا عن استشارة مختص.",identityStartBtn:"ابدأ رحلة التعرف على نفسك",identityPrivacyNote:"🔒 إجاباتك ونتيجتك سرية بالكامل — تُحفظ فقط على جهازك، ولا تُرسَل أو تُشارَك مع أي شخص.",identitySecondaryIntro:"وبداخلك أيضًا جانب واضح من: {trait}",identityInsightLabel:"لحظة من إجاباتك كشفت هذا بوضوح",identityYourChoice:"اختيارك",identitySaveImage:"حفظ النتيجة كصورة",identityRetake:"أعد الاختبار",identityHistoryLabel:"رحلتك عبر الوقت",identityScoresLabel:"توزيع ملامح شخصيتك"});
  Object.assign(T.en,{identityIntroEyebrow:"Personality Analysis",identityIntroTitle:"Before we begin with you…",identityIntroBody:"20 simple questions, no countdown and no pressure. Answer honestly and at your own pace — there's no right or wrong answer, only your real one. All we need is for you to be yourself.",identityIntroDisclaimer:"This is designed to help you understand yourself more deeply, for insight and enjoyment — it is not a medical or clinical diagnosis and isn't a substitute for a qualified professional.",identityStartBtn:"Start discovering yourself",identityPrivacyNote:"🔒 Your answers and result are completely private — saved only on your device, never sent or shared with anyone.",identitySecondaryIntro:"And within you is also a clear touch of: {trait}",identityInsightLabel:"A moment from your answers that showed this clearly",identityYourChoice:"Your choice",identitySaveImage:"Save result as image",identityRetake:"Retake the test",identityHistoryLabel:"Your journey over time",identityScoresLabel:"Your personality breakdown"});
  Object.assign(T.zh,{identityIntroEyebrow:"性格分析",identityIntroTitle:"在我们开始之前…",identityIntroBody:"20个简单的问题，没有倒计时，也没有压力。请按自己的节奏诚实回答——没有对错之分，只有你真实的答案。我们只需要你做真实的自己。",identityIntroDisclaimer:"此分析旨在帮助你更深入、更愉快地了解自己，并非医学或临床诊断，也不能替代专业人士的咨询。",identityStartBtn:"开始认识自己",identityPrivacyNote:"🔒 你的答案和结果完全私密——仅保存在你的设备上，绝不会被发送或与任何人分享。",identitySecondaryIntro:"同时，你身上也明显带有：{trait} 的特质",identityInsightLabel:"你的答案中有一个瞬间清楚地展现了这一点",identityYourChoice:"你的选择",identitySaveImage:"将结果保存为图片",identityRetake:"重新测试",identityHistoryLabel:"你随时间的变化轨迹",identityScoresLabel:"你的性格构成"});
  Object.assign(T.hi,{identityIntroEyebrow:"व्यक्तित्व विश्लेषण",identityIntroTitle:"शुरू करने से पहले…",identityIntroBody:"20 आसान सवाल, कोई टाइमर नहीं और कोई दबाव नहीं। अपनी गति से ईमानदारी से जवाब दें — कोई सही या गलत जवाब नहीं है, सिर्फ आपका असली जवाब। हमें बस इतना चाहिए कि आप खुद बनें रहें।",identityIntroDisclaimer:"यह विश्लेषण आपको खुद को गहराई से और आनंद के साथ समझने में मदद करने के लिए बनाया गया है — यह कोई चिकित्सीय या मनोवैज्ञानिक निदान नहीं है और किसी विशेषज्ञ की सलाह का विकल्प नहीं है।",identityStartBtn:"खुद को जानने की शुरुआत करें",identityPrivacyNote:"🔒 आपके जवाब और नतीजा पूरी तरह निजी हैं — केवल आपके डिवाइस पर सहेजे जाते हैं, किसी के साथ साझा नहीं किए जाते।",identitySecondaryIntro:"और आपके भीतर यह भी साफ़ झलकता है: {trait}",identityInsightLabel:"आपके जवाबों में एक पल जिसने इसे साफ़ दिखाया",identityYourChoice:"आपका चुनाव",identitySaveImage:"नतीजे को इमेज के रूप में सहेजें",identityRetake:"फिर से टेस्ट करें",identityHistoryLabel:"समय के साथ आपकी यात्रा",identityScoresLabel:"आपके व्यक्तित्व का विभाजन"});
  Object.assign(T.es,{identityIntroEyebrow:"Análisis de personalidad",identityIntroTitle:"Antes de empezar contigo…",identityIntroBody:"20 preguntas sencillas, sin cuenta atrás y sin presión. Responde con sinceridad y a tu propio ritmo: no hay respuestas correctas ni incorrectas, solo tu respuesta real. Lo único que necesitamos es que seas tú mismo.",identityIntroDisclaimer:"Este análisis está pensado para ayudarte a comprenderte mejor, de forma reflexiva y entretenida; no es un diagnóstico médico ni clínico, ni sustituye la consulta con un profesional.",identityStartBtn:"Empezar a descubrirme",identityPrivacyNote:"🔒 Tus respuestas y tu resultado son totalmente privados: se guardan solo en tu dispositivo y nunca se envían ni se comparten con nadie.",identitySecondaryIntro:"Y dentro de ti también hay un claro toque de: {trait}",identityInsightLabel:"Un momento de tus respuestas que lo mostró con claridad",identityYourChoice:"Tu elección",identitySaveImage:"Guardar resultado como imagen",identityRetake:"Repetir el test",identityHistoryLabel:"Tu trayectoria a lo largo del tiempo",identityScoresLabel:"El desglose de tu personalidad"});
  Object.assign(T.fr,{identityIntroEyebrow:"Analyse de personnalité",identityIntroTitle:"Avant de commencer avec toi…",identityIntroBody:"20 questions simples, sans chronomètre et sans pression. Réponds sincèrement et à ton rythme — il n'y a pas de bonne ou de mauvaise réponse, seulement la tienne. Tout ce qu'il nous faut, c'est que tu sois toi-même.",identityIntroDisclaimer:"Cette analyse est conçue pour t'aider à mieux te comprendre, avec profondeur et plaisir — ce n'est ni un diagnostic médical ni clinique, et elle ne remplace pas l'avis d'un professionnel.",identityStartBtn:"Commencer à me découvrir",identityPrivacyNote:"🔒 Tes réponses et ton résultat sont totalement privés — enregistrés uniquement sur ton appareil, jamais envoyés ni partagés avec qui que ce soit.",identitySecondaryIntro:"Et en toi se trouve aussi une nette touche de : {trait}",identityInsightLabel:"Un moment de tes réponses qui l'a montré clairement",identityYourChoice:"Ton choix",identitySaveImage:"Enregistrer le résultat en image",identityRetake:"Refaire le test",identityHistoryLabel:"Ton parcours dans le temps",identityScoresLabel:"La répartition de ta personnalité"});
  Object.assign(T.fa,{identityIntroEyebrow:"تحلیل شخصیت",identityIntroTitle:"پیش از شروع با تو…",identityIntroBody:"۲۰ سؤال ساده، بدون شمارش معکوس و بدون فشار. با صداقت و با سرعت خودت پاسخ بده — پاسخ درست یا غلطی وجود ندارد، فقط پاسخ واقعی خودت. تنها چیزی که لازم داریم این است که خودت باشی.",identityIntroDisclaimer:"این تحلیل برای این طراحی شده که به‌شکلی عمیق و لذت‌بخش به شناخت خودت کمک کند — این یک تشخیص پزشکی یا روان‌شناختی نیست و جای مشاوره با یک متخصص را نمی‌گیرد.",identityStartBtn:"شروع سفر شناخت خودم",identityPrivacyNote:"🔒 پاسخ‌ها و نتیجه‌ی تو کاملاً خصوصی است — فقط روی دستگاه خودت ذخیره می‌شود و هرگز ارسال یا با کسی به‌اشتراک گذاشته نمی‌شود.",identitySecondaryIntro:"و درون تو همچنین ردی روشن از این وجود دارد: {trait}",identityInsightLabel:"لحظه‌ای از پاسخ‌هایت که این را به‌روشنی نشان داد",identityYourChoice:"انتخاب تو",identitySaveImage:"ذخیره‌ی نتیجه به‌صورت تصویر",identityRetake:"دوباره آزمون را بده",identityHistoryLabel:"مسیر تو در طول زمان",identityScoresLabel:"تفکیک ویژگی‌های شخصیت تو"});
  /* V1230.76 — Dark Room hub redesign: the room becomes a proper room page (story, creatures, chapters, a basic survival-decision game) with Light Escape (the Epic50 maze) as one feature inside it, not the whole room */
  /* V1230.90 — darkRoomGameIntro/darkRoomGameRewardNote updated: "four" -> "twelve" scenarios, and reward copy corrected to "zero mistakes" (matches actual runSurvival/renderSurvivalResult logic: any single wrong answer ends the run and disqualifies the reward) */
  Object.assign(T.ar,{darkRoomTitle:"الغرفة المظلمة",darkRoomSubtitle:"حيث يُختبر الهدوء تحت الضغط، وحيث يتعلّم العقل أن الظلام لا يُهزم بالركض، بل بالثبات.",darkRoomHeroTitle:"النور لا يُطفأ… هو يُدار بحكمة.",darkRoomHeroText:"قبل ما تدخل المتاهة الحقيقية (الهروب من الظلام، ٥٠ مستوى)، جرّب قرارات البقاء السريعة، تعرّف على الكائنات اللي بتشاركك الظلام، واقرأ فصول الرحلة. كل شي هون جزء من غرفة واحدة.",darkRoomGameCta:"جرّب قرار البقاء",darkRoomGameDone:"✓ اجتزت قرار البقاء",darkRoomChooseLabel:"تصفّح الغرفة",darkRoomTabStory:"القصة",darkRoomTabCreatures:"الكائنات",darkRoomTabChapters:"فصول الرحلة",darkRoomNoteTitle:"ملاحظة",darkRoomNoteText:"أجواء هذه الغرفة مصممة للتوتر الخفيف والتشويق فقط — لا عنف ولا محتوى مخيف بشكل حقيقي. إذا حسّيت إنها مش مناسبة إلك، في غرف تانية كتير بالموقع تقدر تستمتع فيها.",darkRoomExitConfirm:"رح تطلع من الغرفة المظلمة. متأكد؟",darkRoomGameTitle:"قرار البقاء",darkRoomGameBack:"رجوع",darkRoomGameIntro:"اثنا عشر قرارًا سريعًا. أي قرار خاطئ ينهي المحاولة فورًا — تمامًا متل الظلام الحقيقي، ما في وقت للتردد. خُذ نفسًا، وفكّر متل حدا نجا من قبل.",darkRoomGameStepProgress:"القرار {current} من {total}",darkRoomGameCorrect:"صح — نجوت من هاي اللحظة.",darkRoomGameWrong:"للأسف، هاي الحركة كانت غلطتك الأخيرة.",darkRoomGameResultTitle:"انتهت التجربة — {mistakes} خطأ",darkRoomGameFinishGood:"ثبات حقيقي. هيك بالضبط بتنجح بالهروب من الظلام الكبير.",darkRoomGameFinishOk:"نجوت، بس بتردد. الظلام الحقيقي بيسامح أقل من هيك.",darkRoomGameRewardNote:"إنهاء الاثني عشر قرارًا بدون أي خطأ يمنحك مكافأة ZIVO صغيرة.",darkRoomGameClaim:"استلم المكافأة",darkRoomGamePlayAgain:"جرّب مرة ثانية"});
  Object.assign(T.en,{darkRoomTitle:"The Dark Room",darkRoomSubtitle:"Where calm is tested under pressure, and the mind learns that darkness isn't beaten by running — it's beaten by staying steady.",darkRoomHeroTitle:"The light isn't switched off… it's managed with wisdom.",darkRoomHeroText:"Before you step into the real maze (Light Escape, 50 levels), try the quick survival decisions, meet the things that share the dark with you, and read through the journey's chapters. Everything here is part of one room.",darkRoomGameCta:"Try the survival test",darkRoomGameDone:"✓ Survival test cleared",darkRoomChooseLabel:"Explore the room",darkRoomTabStory:"The Story",darkRoomTabCreatures:"Creatures",darkRoomTabChapters:"Chapters",darkRoomNoteTitle:"A note",darkRoomNoteText:"This room's mood is built for light tension and suspense only — no real violence or genuinely scary content. If it's not for you, there are plenty of other rooms on the site to enjoy instead.",darkRoomExitConfirm:"You're about to leave the Dark Room. Are you sure?",darkRoomGameTitle:"The Survival Decision",darkRoomGameBack:"Back",darkRoomGameIntro:"Twelve quick decisions. One wrong choice ends the run instantly — just like the real dark, there's no time to hesitate. Take a breath, and think like someone who's survived this before.",darkRoomGameStepProgress:"Decision {current} of {total}",darkRoomGameCorrect:"Right — you made it through that moment.",darkRoomGameWrong:"Unfortunately, that move was your last mistake.",darkRoomGameResultTitle:"Run over — {mistakes} mistake(s)",darkRoomGameFinishGood:"Real composure. This is exactly how you make it through the big escape.",darkRoomGameFinishOk:"You survived, but with hesitation. The real dark forgives even less than this.",darkRoomGameRewardNote:"Clearing all twelve decisions with zero mistakes earns a small ZIVO reward.",darkRoomGameClaim:"Claim reward",darkRoomGamePlayAgain:"Try again"});
  Object.assign(T.zh,{darkRoomTitle:"暗室",darkRoomSubtitle:"在这里，压力之下的冷静将被考验，心灵会明白：战胜黑暗靠的不是奔跑，而是沉稳。",darkRoomHeroTitle:"光并未熄灭……它是被智慧地掌控着。",darkRoomHeroText:"在进入真正的迷宫（逃离黑暗，50 关）之前，先试试这些快速的生存抉择，认识与你共享黑暗的东西，并读一读旅程的章节。这里的一切都是同一个房间的一部分。",darkRoomGameCta:"试试生存考验",darkRoomGameDone:"✓ 生存考验已通过",darkRoomChooseLabel:"探索房间",darkRoomTabStory:"故事",darkRoomTabCreatures:"暗中之物",darkRoomTabChapters:"旅程章节",darkRoomNoteTitle:"提示",darkRoomNoteText:"这个房间的氛围只是为了营造轻微的紧张和悬念——没有真正的暴力或真正恐怖的内容。如果这不适合你，网站上还有很多其他房间可以尽情享受。",darkRoomExitConfirm:"你即将离开暗室。确定吗？",darkRoomGameTitle:"生存抉择",darkRoomGameBack:"返回",darkRoomGameIntro:"十二个快速抉择。一次错误选择就会立即结束本轮——就像真正的黑暗一样，没有犹豫的时间。深呼吸，像一个曾经活下来的人那样思考。",darkRoomGameStepProgress:"第 {current}/{total} 个抉择",darkRoomGameCorrect:"正确——你挺过了那一刻。",darkRoomGameWrong:"很遗憾，那一步是你犯的最后一个错误。",darkRoomGameResultTitle:"本轮结束——{mistakes} 次失误",darkRoomGameFinishGood:"真正的沉着。这正是你能在那场大逃亡中成功的方式。",darkRoomGameFinishOk:"你活下来了，但犹豫了。真正的黑暗宽容度比这更低。",darkRoomGameRewardNote:"零失误完成全部十二个抉择，可获得少量 ZIVO 奖励。",darkRoomGameClaim:"领取奖励",darkRoomGamePlayAgain:"再试一次"});
  Object.assign(T.hi,{darkRoomTitle:"डार्क रूम",darkRoomSubtitle:"यहाँ दबाव में शांति परखी जाती है, और मन सीखता है कि अंधकार को दौड़कर नहीं, बल्कि स्थिर रहकर हराया जाता है।",darkRoomHeroTitle:"रोशनी बुझती नहीं… इसे समझदारी से संभाला जाता है।",darkRoomHeroText:"असली भूलभुलैया (लाइट एस्केप, 50 स्तर) में जाने से पहले, त्वरित जीवन-रक्षा फ़ैसले आज़माएँ, उन चीज़ों से मिलें जो अंधकार आपके साथ साझा करती हैं, और यात्रा के अध्याय पढ़ें। यहाँ की हर चीज़ एक ही कमरे का हिस्सा है।",darkRoomGameCta:"जीवन-रक्षा परीक्षण आज़माएँ",darkRoomGameDone:"✓ जीवन-रक्षा परीक्षण पूरा हुआ",darkRoomChooseLabel:"कमरे को देखें",darkRoomTabStory:"कहानी",darkRoomTabCreatures:"प्राणी",darkRoomTabChapters:"अध्याय",darkRoomNoteTitle:"एक टिप्पणी",darkRoomNoteText:"इस कमरे का माहौल केवल हल्के तनाव और रोमांच के लिए बनाया गया है — कोई असली हिंसा या सच में डरावनी सामग्री नहीं है। अगर यह आपके लिए नहीं है, तो साइट पर आनंद लेने के लिए और भी कई कमरे मौजूद हैं।",darkRoomExitConfirm:"आप डार्क रूम छोड़ने वाले हैं। क्या आप सुनिश्चित हैं?",darkRoomGameTitle:"जीवन-रक्षा का फ़ैसला",darkRoomGameBack:"वापस",darkRoomGameIntro:"बारह त्वरित फ़ैसले। एक गलत चुनाव तुरंत प्रयास समाप्त कर देता है — बिल्कुल असली अंधेरे की तरह, हिचकिचाने का समय नहीं है। साँस लें, और ऐसे सोचें जैसे कोई पहले भी इससे बच निकला हो।",darkRoomGameStepProgress:"फ़ैसला {current} / {total}",darkRoomGameCorrect:"सही — आप उस पल से बच निकले।",darkRoomGameWrong:"अफ़सोस, वह कदम आपकी आख़िरी गलती थी।",darkRoomGameResultTitle:"प्रयास समाप्त — {mistakes} गलती/गलतियाँ",darkRoomGameFinishGood:"असली धैर्य। बड़े पलायन में सफल होने का यही सही तरीका है।",darkRoomGameFinishOk:"आप बच गए, पर हिचकिचाहट के साथ। असली अंधेरा इससे भी कम माफ़ करता है।",darkRoomGameRewardNote:"बिना किसी गलती के सभी बारह फ़ैसलों को पूरा करने पर छोटा ZIVO इनाम मिलता है।",darkRoomGameClaim:"इनाम लें",darkRoomGamePlayAgain:"फिर कोशिश करें"});
  Object.assign(T.es,{darkRoomTitle:"La Sala Oscura",darkRoomSubtitle:"Donde se pone a prueba la calma bajo presión, y la mente aprende que la oscuridad no se vence corriendo, sino manteniéndose firme.",darkRoomHeroTitle:"La luz no se apaga… se administra con sabiduría.",darkRoomHeroText:"Antes de entrar al laberinto real (Escape de Luz, 50 niveles), prueba las decisiones rápidas de supervivencia, conoce a las criaturas que comparten la oscuridad contigo y lee los capítulos del viaje. Todo esto es parte de una sola sala.",darkRoomGameCta:"Prueba el test de supervivencia",darkRoomGameDone:"✓ Test de supervivencia superado",darkRoomChooseLabel:"Explora la sala",darkRoomTabStory:"La Historia",darkRoomTabCreatures:"Criaturas",darkRoomTabChapters:"Capítulos",darkRoomNoteTitle:"Una nota",darkRoomNoteText:"El ambiente de esta sala está pensado solo para una tensión ligera y suspenso — sin violencia real ni contenido verdaderamente aterrador. Si no es para ti, hay muchas otras salas en el sitio para disfrutar.",darkRoomExitConfirm:"Estás a punto de salir de la Sala Oscura. ¿Estás seguro?",darkRoomGameTitle:"La Decisión de Supervivencia",darkRoomGameBack:"Volver",darkRoomGameIntro:"Doce decisiones rápidas. Una elección equivocada termina el intento al instante, igual que en la oscuridad real: no hay tiempo para dudar. Respira hondo y piensa como alguien que ya sobrevivió a esto antes.",darkRoomGameStepProgress:"Decisión {current} de {total}",darkRoomGameCorrect:"Correcto: saliste adelante en ese momento.",darkRoomGameWrong:"Lamentablemente, ese movimiento fue tu último error.",darkRoomGameResultTitle:"Intento terminado — {mistakes} error(es)",darkRoomGameFinishGood:"Serenidad de verdad. Así es exactamente como se logra la gran fuga.",darkRoomGameFinishOk:"Sobreviviste, pero con dudas. La oscuridad real perdona incluso menos que esto.",darkRoomGameRewardNote:"Superar las doce decisiones sin ningún error te da una pequeña recompensa ZIVO.",darkRoomGameClaim:"Reclamar recompensa",darkRoomGamePlayAgain:"Intentar de nuevo"});
  Object.assign(T.fr,{darkRoomTitle:"La Pièce Sombre",darkRoomSubtitle:"Là où le calme est mis à l'épreuve sous pression, et où l'esprit apprend que l'obscurité ne se vainc pas en courant, mais en restant ferme.",darkRoomHeroTitle:"La lumière ne s'éteint pas… elle se gère avec sagesse.",darkRoomHeroText:"Avant d'entrer dans le vrai labyrinthe (Évasion de Lumière, 50 niveaux), essaie les décisions de survie rapides, découvre les créatures qui partagent l'obscurité avec toi, et lis les chapitres du voyage. Tout ici fait partie d'une seule pièce.",darkRoomGameCta:"Essaie le test de survie",darkRoomGameDone:"✓ Test de survie réussi",darkRoomChooseLabel:"Explore la pièce",darkRoomTabStory:"L'Histoire",darkRoomTabCreatures:"Créatures",darkRoomTabChapters:"Chapitres",darkRoomNoteTitle:"Une note",darkRoomNoteText:"L'ambiance de cette pièce est conçue uniquement pour une légère tension et du suspense — aucune violence réelle ni contenu véritablement effrayant. Si ce n'est pas pour toi, il y a plein d'autres pièces sur le site à découvrir.",darkRoomExitConfirm:"Tu es sur le point de quitter la Pièce Sombre. Es-tu sûr ?",darkRoomGameTitle:"La Décision de Survie",darkRoomGameBack:"Retour",darkRoomGameIntro:"Douze décisions rapides. Un seul mauvais choix met fin à la tentative instantanément — tout comme dans l'obscurité réelle, pas le temps d'hésiter. Respire un coup, et pense comme quelqu'un qui a déjà survécu à ça.",darkRoomGameStepProgress:"Décision {current} sur {total}",darkRoomGameCorrect:"Correct : tu as survécu à ce moment-là.",darkRoomGameWrong:"Malheureusement, ce choix a été ta dernière erreur.",darkRoomGameResultTitle:"Tentative terminée — {mistakes} erreur(s)",darkRoomGameFinishGood:"Un vrai sang-froid. C'est exactement comme ça qu'on réussit la grande évasion.",darkRoomGameFinishOk:"Tu as survécu, mais avec hésitation. L'obscurité réelle pardonne encore moins que ça.",darkRoomGameRewardNote:"Réussir les douze décisions sans aucune erreur te donne une petite récompense ZIVO.",darkRoomGameClaim:"Réclamer la récompense",darkRoomGamePlayAgain:"Réessayer"});
  Object.assign(T.fa,{darkRoomTitle:"اتاق تاریک",darkRoomSubtitle:"جایی که آرامش زیر فشار آزمایش می‌شود، و ذهن می‌آموزد که تاریکی با دویدن شکست نمی‌خورد، بلکه با ثبات شکست می‌خورد.",darkRoomHeroTitle:"نور خاموش نمی‌شود… با خردمندی مدیریت می‌شود.",darkRoomHeroText:"پیش از ورود به هزارتوی واقعی (فرار از نور، ۵۰ مرحله)، تصمیم‌های سریع بقا را امتحان کن، با موجوداتی که تاریکی را با تو شریک می‌شوند آشنا شو، و فصل‌های این سفر را بخوان. همه‌چیز اینجا بخشی از یک اتاق است.",darkRoomGameCta:"آزمون بقا را امتحان کن",darkRoomGameDone:"✓ آزمون بقا با موفقیت انجام شد",darkRoomChooseLabel:"اتاق را کاوش کن",darkRoomTabStory:"داستان",darkRoomTabCreatures:"موجودات",darkRoomTabChapters:"فصل‌ها",darkRoomNoteTitle:"یک نکته",darkRoomNoteText:"فضای این اتاق فقط برای هیجان و تعلیق ملایم طراحی شده — بدون خشونت واقعی یا محتوای واقعاً ترسناک. اگر این مناسب تو نیست، اتاق‌های دیگر زیادی در سایت هست که می‌توانی از آن‌ها لذت ببری.",darkRoomExitConfirm:"در حال خروج از اتاق تاریک هستی. مطمئنی؟",darkRoomGameTitle:"تصمیم بقا",darkRoomGameBack:"بازگشت",darkRoomGameIntro:"دوازده تصمیم سریع. یک انتخاب اشتباه بلافاصله به تلاش پایان می‌دهد — درست مثل تاریکی واقعی، وقتی برای تردید نیست. نفس عمیقی بکش و مثل کسی فکر کن که قبلاً از این جان سالم به در برده.",darkRoomGameStepProgress:"تصمیم {current} از {total}",darkRoomGameCorrect:"درست بود — از آن لحظه جان سالم به در بردی.",darkRoomGameWrong:"متأسفانه، آن حرکت آخرین اشتباه تو بود.",darkRoomGameResultTitle:"تلاش پایان یافت — {mistakes} اشتباه",darkRoomGameFinishGood:"خونسردی واقعی. دقیقاً همین‌طوری است که در فرار بزرگ موفق می‌شوی.",darkRoomGameFinishOk:"جان سالم به در بردی، اما با تردید. تاریکی واقعی حتی کمتر از این می‌بخشد.",darkRoomGameRewardNote:"تکمیل هر دوازده تصمیم بدون هیچ اشتباهی، پاداش کوچک ZIVO می‌دهد.",darkRoomGameClaim:"دریافت پاداش",darkRoomGamePlayAgain:"دوباره امتحان کن"});
